class Solution {
public:
    int orderOfLargestPlusSign(int n, vector<vector<int>>& mines) {
        vector<vector<int>> grid(n, vector<int>(n, 1));
        for (auto& m : mines) grid[m[0]][m[1]] = 0;

        vector<vector<int>> left(n, vector<int>(n, 0));
        vector<vector<int>> right(n, vector<int>(n, 0));
        vector<vector<int>> up(n, vector<int>(n, 0));
        vector<vector<int>> down(n, vector<int>(n, 0));

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c]) left[r][c] = (c == 0 ? 1 : left[r][c - 1] + 1);
            }
            for (int c = n - 1; c >= 0; c--) {
                if (grid[r][c]) right[r][c] = (c == n - 1 ? 1 : right[r][c + 1] + 1);
            }
        }
        for (int c = 0; c < n; c++) {
            for (int r = 0; r < n; r++) {
                if (grid[r][c]) up[r][c] = (r == 0 ? 1 : up[r - 1][c] + 1);
            }
            for (int r = n - 1; r >= 0; r--) {
                if (grid[r][c]) down[r][c] = (r == n - 1 ? 1 : down[r + 1][c] + 1);
            }
        }

        int ans = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c]) {
                    int k = min(min(left[r][c], right[r][c]), min(up[r][c], down[r][c]));
                    if (k > ans) ans = k;
                }
            }
        }
        return ans;
    }
};
